USE inkspell_db;
SELECT 'The Silent Patient','Alex Michaelides',id,'A therapist seeks the truth behind an artist''s silence after a killing.',
'9781250301697','https://covers.openlibrary.org/b/isbn/9781250301697-L.jpg',0,1 FROM genres WHERE name='Thriller' AND NOT EXISTS(SELECT 1 FROM books WHERE isbn='9781250301697');

