'9781982183780','https://covers.openlibrary.org/b/isbn/9781982183780-L.jpg',0,1 FROM genres WHERE name='Thriller' AND NOT EXISTS(SELECT 1 FROM books WHERE isbn='9781982183780');

SELECT 'Does It Hurt?','Zoe York',id,'A modern romance exploring love, loss, and the pain of letting go.',
'9781451668960','https://covers.openlibrary.org/b/isbn/9781451668960-L.jpg',0,1 FROM genres WHERE name='Contemporary Fiction' AND NOT EXISTS(SELECT 1 FROM books WHERE isbn='9781451668960');

UPDATE books SET is_featured=0 WHERE is_featured=1 AND id<>(SELECT id FROM (SELECT MIN(id) id FROM books WHERE is_featured=1) chosen);
UPDATE books SET is_featured=1 WHERE id=(SELECT id FROM (SELECT id FROM books ORDER BY is_featured DESC,id LIMIT 1) chosen);
